OAuth:
export async function GET({ cookies, url, locals }) {
  const code = url.searchParams.get('code');
  const { tokens } = await githubAuth.validateAuthorizationCode(code);
  locals.user = await createUserFromGithub(tokens);
  return new Response(null, { status: 302, headers: { location: '/' } });
}

Hooks:
export async function handle({ event, resolve }) {
  if (event.url.pathname.startsWith('/api')) {
    event.request.headers.set('X-API-Key', process.env.API_KEY);
  }
  return resolve(event);
}

Client Navigation:
export function onNavigate() {
  document.startViewTransition ?
    document.startViewTransition(() => {}) :
    null;
}

Cross-document Transitions:
/* global.css */
@view-transition {
  navigation: auto;
}

@keyframes fade-in {
  from { opacity: 0; }
}
::view-transition-old(root) { animation: fade-in 0.3s reverse; }
::view-transition-new(root) { animation: fade-in 0.3s; }
